"""Tarjeta de bienvenida de Simón dentro del chat (con tu dibujo), cada vez que se abre.
Ejecutar dentro de la carpeta del proyecto:  python instalar_bienvenida.py
Se puede repetir sin problema. Guarda copia chat.js.bak"""
import base64, zlib, pathlib, shutil

ARCHIVOS = {
    'static/js/simon.js': "",
    'static/css/simon.css': "",
    'static/img/simon-bienvenida.png': "",
}

raiz = pathlib.Path.cwd()
if not (raiz / "app.py").exists() or not (raiz / "static").is_dir():
    raise SystemExit("Esta no es la carpeta del proyecto (no veo app.py ni static).\n"
                     "Entra con:  cd %USERPROFILE%\\bienestarbot   y vuelve a ejecutar.")
print("Carpeta del proyecto:", raiz)
for ruta, datos in ARCHIVOS.items():
    d = raiz / ruta
    d.parent.mkdir(parents=True, exist_ok=True)
    d.write_bytes(zlib.decompress(base64.b64decode(datos)))
    print("  escrito:", ruta)

# El chat espera a que la persona pulse «¡Hablemos!» para saludar.
f = raiz / "static/js/chat.js"
t = f.read_text(encoding="utf-8")
if "simonChatIniciar" in t:
    print("chat.js: ya estaba aplicado")
else:
    cambios = [
        ("    if (!iniciado) { iniciado = true; enviar({ accion: 'menu' }, null); }",
         "    if (!iniciado && !document.body.classList.contains('simon-on')) { iniciado = true; enviar({ accion: 'menu' }, null); }"),
        ("    if (ocupado) return;\n    ocupado = true;",
         "    if (ocupado) return;\n    ocupado = true;\n    iniciado = true;"),
        ("  fab.addEventListener('click', function () { if (pop.hidden) abrir(); else cerrar(); });",
         "  window.simonChatIniciar = function () { if (!iniciado) { iniciado = true; enviar({ accion: 'menu' }, null); } };\n"
         "  fab.addEventListener('click', function () { if (pop.hidden) abrir(); else cerrar(); });"),
    ]
    for viejo, nuevo in cambios:
        if t.count(viejo) != 1:
            raise SystemExit("No encontre este punto en chat.js (no cambie nada):\n" + viejo[:80])
        t = t.replace(viejo, nuevo)
    shutil.copy(f, str(f) + ".bak")
    f.write_text(t, encoding="utf-8")
    print("chat.js: actualizado")

print("\n===== VERIFICACION =====")
print("tarjeta de bienvenida :", "SI" if "simon-tarjeta" in (raiz / "static/js/simon.js").read_text(encoding="utf-8") else "NO")
print("chat espera a Hablemos:", "SI" if "simonChatIniciar" in (raiz / "static/js/chat.js").read_text(encoding="utf-8") else "NO")
print("\nReinicia el servidor (Ctrl+C y python app.py) y recarga con Ctrl+F5.")
